"use strict";
// Session Logs for the Eclipse plugin: VS Code's log reading (log-report.js), its snapshot page (log-snapshot.js) and
// its reading of a logged object (session-log.js), as one script for the plugin's browser. Java reads and deletes the
// files; parsing and the pages are VS Code's. Node's fs and path are not there: what needs them throws when used, and
// the parts used here do not. crypto gives the snapshot page its nonce from the browser's own random source.
const fs = require("node:fs");
const path = require("node:path");

const MODULES = ["log-report", "log-snapshot", "session-log"];

function bundle(root = path.join(__dirname, "..")) {
  const parts = MODULES.map(name => JSON.stringify("./" + name) + ": function (module, exports, require) {\n"
    + fs.readFileSync(path.join(root, "vscode", name + ".js"), "utf8") + "\n}");
  return "// Generated by eclipse/prepare.js from vscode/" + MODULES.join(".js, vscode/") + ".js - edit those.\n"
    + "(function (root) {\n"
    + "var unavailable = function (name) { return new Proxy({}, { get: function () { return function () { throw new Error('Node ' + name + ' is not available in the Eclipse browser.'); }; } }); };\n"
    + "var crypto = { randomBytes: function (n) { var bytes = new Uint8Array(n); root.crypto.getRandomValues(bytes);\n"
    + "  return { toString: function () { return Array.prototype.map.call(bytes, function (b) { return (b < 16 ? '0' : '') + b.toString(16); }).join(''); } }; } };\n"
    + "var modules = {\n" + parts.join(",\n") + "\n};\n"
    + "var cache = {};\n"
    + "function load(name) {\n"
    + "  if (name === 'fs' || name === 'path') { return unavailable(name); }\n"
    + "  if (name === 'crypto') { return crypto; }\n"
    + "  if (!Object.prototype.hasOwnProperty.call(modules, name)) { throw new Error('Session Logs in Eclipse has no module ' + name + '.'); }\n"
    + "  if (!cache[name]) { var module = { exports: {} }; cache[name] = module; try { modules[name](module, module.exports, load); } catch (error) { delete cache[name]; throw error; } }\n"
    + "  return cache[name].exports;\n"
    + "}\n"
    + "root.vertexLogs = { parseSession: load('./log-report').parseSession, snapshotHtml: load('./log-snapshot').html,\n"
    + "  objectReference: load('./session-log').objectReference };\n"
    + "})(typeof window !== 'undefined' ? window : this);\n";
}

module.exports = { bundle, MODULES };
